pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint128 v1, uint128 v2, address actor) public {
        vm.assume(actor != address(0));
        vm.deal(actor, uint256(v1) + uint256(v2));

        vm.startPrank(actor);
        c.Put{value: uint256(v1)}(0);
        uint256 afterFirst = c.Acc(actor).balance;
        assertTrue(afterFirst == uint256(v1), "first deposit sets balance to v1");
        c.Put{value: uint256(v2)}(0);
        vm.stopPrank();

        // General rule: repeated deposits accumulate additively.
        assertTrue(c.Acc(actor).balance == afterFirst + uint256(v2), "deposits accumulate");
    }
}

