pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount1, uint256 amount2, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        uint256 minSum = c.MinSum();
        // First deposit alone is below MinSum, but the two together reach it.
        vm.assume(amount1 > 0 && amount1 < minSum);
        vm.assume(amount2 > 0 && amount2 < minSum && amount1 + amount2 >= minSum);

        vm.deal(actor, amount1 + amount2 + 1 ether);
        vm.prank(actor);
        c.Put{value: amount1}(0);
        vm.prank(actor);
        c.Put{value: amount2}(uint256(0));

        // Move past any unlock time set.
        vm.warp(block.timestamp + 2);

        // The accumulated balance (v1+v2 >= MinSum) must allow a withdrawal.
        bool ok;
        vm.prank(actor);
        try c.Collect(1) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "Collect must succeed once accumulated deposits reach MinSum");
    }
}

