pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 v1, uint256 v2, address actor, uint256 t) public {
        vm.assume(actor != address(0));
        v2 = bound(v2, 1 ether, 2 ** 128);
        v1 = bound(v1, 1, v2);
        t = bound(t, 1, 1000);

        vm.deal(actor, v1 + v2);
        vm.startPrank(actor);
        c.Put{value: v1}(0);
        c.Put{value: v2}(0);
        vm.warp(block.timestamp + t);
        c.Collect(v1);
        vm.stopPrank();

        // Rule: additive accounting - after depositing v1 then v2 and withdrawing v1,
        // the accumulated balance still holds the second deposit v2.
        assertTrue(c.Acc(actor).balance == v2);
    }
}

