pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }
    function testFuzz_property(uint256 v1, uint256 v2, uint256 w, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        v1 = bound(v1, 0, 100 ether);
        v2 = bound(v2, 0, 100 ether);
        vm.assume(v1 + v2 >= 1 ether); // admissible: account must reach MinSum
        w = bound(w, 0, v1 + v2);      // withdrawal must not exceed accumulated balance

        vm.deal(actor, v1 + v2);
        vm.prank(actor);
        c.Put{value: v1}(0);
        vm.prank(actor);
        c.Put{value: v2}(0);

        // funds must have accumulated additively
        assertEq(address(c).balance, v1 + v2);

        vm.warp(block.timestamp + 1 days);
        vm.prank(actor);
        c.Collect(w);

        // conservation rule: remaining balance equals deposits minus withdrawal
        assertTrue(c.Acc(actor).balance == (v1 + v2) - w);
    }
}

