pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log lg;

    function setUp() public {
        lg = new Log();
        c = new C(address(lg));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 100 ether);
        vm.deal(actor, amount);
        uint256 before = lg.History(lg.History.length - 1) == bytes32(0) ? 0 : 0;
        before; // silence unused warning pattern
        uint256 lenBefore;
        // read current history length via last index probing: Log exposes History(uint) getter only,
        // so use array length indirectly: History is public array; Foundry allows .History(idx).
        // Determine length by try/catch probe.
        uint256 lo = 0;
        uint256 hi = 2;
        while (true) {
            try lg.History(hi - 1) returns (address, string memory, uint256, uint256) {
                lo = hi;
                hi = hi * 2;
            } catch {
                break;
            }
        }
        lenBefore = lo;
        vm.prank(actor);
        c.Put{value: amount}(0);
        assertTrue(lg.History(lenBefore) == (address(actor)) || (tryGet(lenBefore) == actor), "deposit must be logged");
    }

    function tryGet(uint256 idx) internal view returns (address) {
        try lg.History(idx) returns (address a, string memory, uint256, uint256) {
            return a;
        } catch {
            return address(0);
        }
    }
}

