pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public {
        log = new Log();
        c = new C(address(log));
    }

    function testFuzz_property(uint256 amount1, uint256 amount2, address actor1, address actor2) public {
        vm.assume(actor1 != address(0) && actor2 != address(0) && actor1 != address(c));
        vm.assume(amount1 > 0 && amount2 > 0);

        vm.deal(actor1, amount1);
        vm.prank(actor1);
        (bool ok1, ) = address(c).call{value: amount1}(abi.encodeWithSignature("Put(uint256)", uint256(0)));
        assertTrue(ok1);

        vm.deal(actor2, amount2);
        vm.prank(actor2);
        (bool ok2, ) = address(c).call{value: amount2}(abi.encodeWithSignature("Put(uint256)", uint256(0)));
        assertTrue(ok2);

        // General rule: deposits are recorded in order — History entry 0 records the
        // first deposit's value and entry 1 records the second deposit's value.
        (, , uint256 val0, ) = log.History(0);
        (, , uint256 val1, ) = log.History(1);
        assertTrue(val0 == amount1 && val1 == amount2);
    }
}

